DELIMITER $$
CREATE PROCEDURE seed_books() BEGIN DECLARE i INT DEFAULT 1; WHILE i<=30 DO INSERT INTO books(title,isbn,description,publication_year,pages,language,author_id,publisher_id,category_id) VALUES(CONCAT('Library Collection Volume ',i),CONCAT('978000000',LPAD(i,4,'0')),CONCAT('A fictional sample library book, volume ',i,'.'),2010+i,180+i,'English',1+MOD(i-1,10),1+MOD(i-1,5),1+MOD(i-1,8)); SET i=i+1; END WHILE; END$$
CALL seed_books()$$ DROP PROCEDURE seed_books$$
CREATE PROCEDURE seed_copies() BEGIN DECLARE i INT DEFAULT 1; DECLARE n INT DEFAULT 1; WHILE i<=30 DO SET n=1; WHILE n<=2 DO INSERT INTO book_copies(book_id,accession_number,status,location,`condition`) VALUES(i,CONCAT('BR-',LPAD(i,3,'0'),'-',LPAD(n,2,'0')),'AVAILABLE',CONCAT('Shelf ',1+MOD(i,9)),'Good'); SET n=n+1; END WHILE; SET i=i+1; END WHILE; END$$
CALL seed_copies()$$ DROP PROCEDURE seed_copies$$
DELIMITER ;
